export async function reportHealth(services) {
  const values = await Promise.all(services.map((service) => service.check()));
  return services.map((service, index) => ({ name: service.name, ok: values[index] }));
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { reportHealth } from '../src/health.js';

const hidup = async () => true;
const mati = async () => {
  throw new Error('connection timeout');
};

test('service yang mati tidak menghapus hasil yang lain', async () => {
  const report = await reportHealth([
    { name: 'api', check: hidup },
    { name: 'db', check: mati },
  ]);
  assert.deepEqual(report, [
    { name: 'api', ok: true },
    { name: 'db', ok: false },
  ]);
});

test('semua sehat tercatat sehat', async () => {
  assert.deepEqual(await reportHealth([{ name: 'api', check: hidup }]), [
    { name: 'api', ok: true },
  ]);
});

test('daftar kosong menghasilkan laporan kosong', async () => {
  assert.deepEqual(await reportHealth([]), []);
});

test('service yang jawab false ya false, bukan ikut hitung', async () => {
  const lemas = async () => false;
  assert.deepEqual(await reportHealth([{ name: 'cache', check: lemas }]), [
    { name: 'cache', ok: false },
  ]);
});

