export async function reportHealth(services) {
  const settled = await Promise.allSettled(services.map((service) => service.check()));
  return services.map((service, index) => ({
    name: service.name,
    ok: settled[index].status === 'fulfilled' ? settled[index].value : false,
  }));
}
